// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/readyz", wrapper.GetReadiness)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/login", wrapper.StartLogin)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/callback", wrapper.CompleteLogin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/auth/homeassistant/callback", wrapper.CompleteHomeConnection)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/households", wrapper.ListHouseholds)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/households", wrapper.CreateHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/households/{householdId}", wrapper.GetHousehold)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/households/{householdId}/invites", wrapper.CreateInvite)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/invites/{code}", wrapper.AcceptInvite)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/households/{householdId}/questions", wrapper.ListQuestions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/households/{householdId}/questions", wrapper.AskQuestion)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/questions/{questionId}/answer", wrapper.AnswerQuestion)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/households/{householdId}/cook/suggestions", wrapper.SuggestRecipes)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/households/{householdId}/recipes/{slug}", wrapper.GetRecipe)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/households/{householdId}/shopping-list", wrapper.AddToShoppingList)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/households/{householdId}/home", wrapper.GetHome)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/households/{householdId}/home/connection", wrapper.DisconnectHome)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/households/{householdId}/home/connection", wrapper.ConnectHome)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/households/{householdId}/home/scenes/{sceneId}", wrapper.ActivateScene)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/households/{householdId}/home/lights/{lightId}/toggle", wrapper.ToggleLight)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/push", wrapper.GetPushConfig)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/push/subscriptions", wrapper.UnsubscribePush)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/push/subscriptions", wrapper.SubscribePush)
	})

	return r
}

